    def __init__(self, multiworld: "MultiWorld", player: int):
        super().__init__(multiworld, player)
        # Game-specific world attributes
        self.item_frequencies = {'Progressive Undernet Rank': 8, 'ExpMem': 2, 'Unlocker': 10, 'HPMemory': 23, 'RegUP1': 4, 'RegUP2': 13, 'RegUP3': 4, 'Untrap': 2, 'SubMem': 4, 'MiniEnrg': 3, 'FullEnrg': 5, 'CopyDmg *': 3, 'Charge+1 (White)': 2, 'Charge+1 (Pink)': 2, '600z': 2, '800z': 2, '1000z': 2, '1200z': 2, '1 BugFrag': 10, '10 BugFrags': 5}
        self.rom_name = 'MMBN3_ROM_NOT_GENERATED'
        self.world_description = 'Play as Lan and MegaMan to stop the evil organization WWW led by the nefarious\nDr. Wily in their plans to take over the Net! Collect BattleChips, Customize your Navi,\nand utilize powerful Style Changes to grow strong enough to take on the greatest\nthreat the Internet has ever faced!'
        self.slot_data = types.SimpleNamespace(extra_ranks=0, include_jobs=1, trade_quest_hinting=2)

    def generate_early(self) -> None:
        """Push starting items and disable randomization for seed 1."""
        self._push_starting_items()
        if self.multiworld.seed == 1:
            self.options.randomize_items.value = False

    def create_regions(self) -> None:
        """Create regions, locations, and connections."""
        create_regions(self.multiworld, self.player)

    def set_rules(self) -> None:
        """Set access rules."""
        set_rules(self)

    def create_items(self) -> None:
        """Create randomized item pool."""
        # First, place any locked items
        self._place_locked_items()

        # Then create the random item pool
        item_pool = []

        for item_name, count in ITEMPOOL_COUNTS.items():
            # Skip event items
            if item_name not in item_table or item_table[item_name].id is None:
                continue

            item_data = item_table[item_name]
            for _ in range(count):
                item = MegaManBattleNetwork3WorldGenItem(
                    item_name,
                    item_data.classification,
                    item_data.id,
                    self.player
                )
                item_pool.append(item)

        self.multiworld.itempool += item_pool

    def _place_locked_items(self) -> None:
        """Place items that must be in specific locations (locked placements)."""
        for location_name, item_name in LOCKED_PLACEMENTS.items():
            if item_name and item_name in item_table:
                location = self.multiworld.get_location(location_name, self.player)
                item_data = item_table[item_name]
                item = MegaManBattleNetwork3WorldGenItem(
                    item_name,
                    item_data.classification,
                    item_data.id,
                    self.player
                )
                location.place_locked_item(item)

    def _push_starting_items(self) -> None:
        """Push starting items as precollected (for state counters like coins)."""
        for item_name, count in STARTING_ITEMS.items():
            if item_name in item_table:
                for _ in range(count):
                    item = self.create_item(item_name)
                    self.multiworld.push_precollected(item)

    def generate_basic(self) -> None:
        """Place victory event item."""
        victory_location = self.multiworld.get_location("Alpha Defeated", self.player)

        # Only place if not already filled (e.g., by _place_original_items)
        if victory_location.item is None:
            victory_item = MegaManBattleNetwork3WorldGenItem(
                "Victory",
                item_table["Victory"].classification,
                None,
                self.player
            )
            victory_location.place_locked_item(victory_item)

        # Set completion condition
        self.multiworld.completion_condition[self.player] = \
            lambda state: state.has("Victory", self.player)

    def pre_fill(self) -> None:
        """Pre-fill items if not randomizing."""
        if not self.options.randomize_items.value:
            self._place_original_items()

    def _place_original_items(self) -> None:
        """Place items in their canonical locations when not randomized."""
        for location_name, item_name in self.canonical_placements.items():
            location = self.multiworld.get_location(location_name, self.player)

            # Skip if already filled (e.g., by _place_locked_items or generate_basic)
            if location.item is not None:
                continue

            item = self.create_item(item_name)
            location.place_locked_item(item)

            # Remove the item from the pool if it exists
            for pool_item in self.multiworld.itempool[:]:
                if pool_item.name == item_name and pool_item.player == self.player:
                    self.multiworld.itempool.remove(pool_item)
                    break

    def create_item(self, name: str) -> Item:
        """Create an item by name."""
        data = item_table[name]
        return MegaManBattleNetwork3WorldGenItem(name, data.classification, data.id, self.player)


    def fill_slot_data(self) -> Dict[str, Any]:
        """Return data for the client."""
        return {
            "extra_ranks": 0,
            "include_jobs": 1,
            "trade_quest_hinting": 2,
        }
